33	pub struct Policy<'a> {
34	    insured: &'a [Item],
35	}
36	
37	impl<'a> Policy<'a> {
38	    pub fn insuring(items: &'a [Item]) -> Self {
39	        Policy { insured: items }
40	    }
41	
42	    /// The insured item a reported damage refers to.
43	    fn damaged_item(&self, damage: &Damage) -> Option<&Item> {
44	        self.insured
45	            .iter()
46	            .find(|item| item.item_type == damage.item_type)
47	    }
48	
49	    /// A settlement totals what the office reimburses for each damage the
50	    /// incident reported.
51	    pub fn claim(&self, damages: &[Damage]) -> Settlement {
52	        let payout = damages
53	            .iter()
54	            .map(|damage| damage_reimbursement(damage, self.damaged_item(damage)))
55	            .sum();
56	        Settlement { payout }
57	    }
58	}
59	
60	/// A premium is rounded in the MHPCO's favor, which for money the customer
61	/// owes the office means upwards.
62	fn round_premium_in_mhpco_favor(premium: f64) -> i64 {
63	    premium.ceil() as i64
64	}
65	
66	/// How the MHPCO's two kinds of modifier reach the premium: policy-wide
67	/// modifiers scale the policy base premium, while item-specific modifiers are
68	/// measured against their own item's base premium and are added alongside, so
69	/// a curse never surcharges the rest of the policy.
70	fn premium_before_fee(customer: &Customer, items: &[Item], previous_quotes: usize) -> f64 {
71	    let base = policy_base_premium(items);
72	    base + standing_adjustment(base, customer, previous_quotes) + item_risk_surcharges(items)
73	}
74	
75	pub fn quote(customer: &Customer, items: &[Item], previous_quotes: usize) -> i64 {
76	    let premium = premium_before_fee(customer, items, previous_quotes);
77	    round_premium_in_mhpco_favor(premium) + PROCESSING_FEE
78	}
