     1	//! What the MHPCO reimburses for a single reported damage: the clauses the
     2	//! office applies to one damage amount before it reaches the settlement.
     3	//!
     4	//! This is the claim side's judgement of a single damage event. It changes
     5	//! when the office revises its clauses -- a steeper deductible, a new
     6	//! material that is fully covered, a different enchantment level -- quite
     7	//! independently of the policy-wide limits on what a settlement may total,
     8	//! and independently of how the premium side assessed the same item's risk.
     9	
    10	use crate::{Damage, Item};
    11	
    12	/// A deductible applies per damage event.
    13	const DEDUCTIBLE: i64 = 100;
    14	
    15	/// Damage to an item enchanted at this level or above is reimbursed at half.
    16	const HALF_REIMBURSEMENT_LEVEL: i64 = 8;
    17	
    18	/// Whether the half-reimbursement clause applies to a damaged item. The claim
    19	/// side judges high enchantment by its own level, well above the one the
    20	/// premium side surcharges for.
    21	fn triggers_half_reimbursement(item: &Item) -> bool {
    22	    item.enchantment >= HALF_REIMBURSEMENT_LEVEL
    23	}
    24	
